import pandas as pd
from collections import Counter

df = pd.read_csv('/app/benchmark/data.csv')

# Let's compute month-over-month growth for keywords properly
# We need to look at monthly counts for keywords and find ones with sustained growth
monthly_kw = {}
for _, row in df.iterrows():
    if pd.notna(row['keywords']) and row['pub_month'] != 'Unknown':
        kws = [k.strip() for k in str(row['keywords']).split(';')]
        ym = f"{row['pub_year']}-{row['pub_month_num']:02d}"
        for kw in kws:
            if kw not in monthly_kw:
                monthly_kw[kw] = {}
            monthly_kw[kw][ym] = monthly_kw[kw].get(ym, 0) + 1

# Find keywords with at least 3 months of data and positive average MoM growth
ym_order = []
for y in [2024, 2025, 2026]:
    for m in range(1, 13):
        ym_order.append(f"{y}-{m:02d}")

kw_mom_growth = []
for kw, months in monthly_kw.items():
    if len(months) >= 3:
        # Build ordered series
        vals = [months.get(ym, 0) for ym in ym_order if ym in months or any(ym in months for ym in ym_order)]
        # Only use months that appear in the dataset for this keyword
        present = [(ym, months.get(ym, 0)) for ym in ym_order if ym in months]
        if len(present) >= 3:
            vals = [v for _, v in present]
            changes = []
            for i in range(1, len(vals)):
                if vals[i-1] > 0:
                    changes.append((vals[i] - vals[i-1]) / vals[i-1] * 100)
                elif vals[i] > 0:
                    changes.append(100.0)  # from 0 to something
                else:
                    changes.append(0.0)
            avg_growth = sum(changes) / len(changes)
            total = sum(vals)
            kw_mom_growth.append((kw, round(avg_growth, 1), total, len(present)))

# Sort by avg growth, filter for meaningful volume (total >= 5)
kw_mom_growth = [x for x in kw_mom_growth if x[2] >= 5]
kw_mom_growth.sort(key=lambda x: x[1], reverse=True)
print("Top keywords by avg month-over-month growth (min 5 total, 3+ months):")
for item in kw_mom_growth[:20]:
    print(item)
